// Custom init when synthesized version isn't enough
struct LooseInt: Codable {
  let value: Int
  init(from decoder: Decoder) throws {
    let c = try decoder.singleValueContainer()
    if let i = try? c.decode(Int.self) { value = i }
    else if let s = try? c.decode(String.self), let i = Int(s) { value = i }
    else { throw DecodingError.dataCorruptedError(in: c, debugDescription: "Bad int") }
  }
  func encode(to encoder: Encoder) throws { var c = encoder.singleValueContainer(); try c.encode(value) }
}

