// ── Implementation sketch (AppMacros target, uses SwiftSyntax) ──
public struct URLMacro: ExpressionMacro {
  public static func expansion(
    of node: some FreestandingMacroExpansionSyntax,
    in context: some MacroExpansionContext
  ) throws -> ExprSyntax {
    guard let literal = node.arguments.first?.expression
            .as(StringLiteralExprSyntax.self),
          let text = literal.representedLiteralValue,
          URL(string: text) != nil
    else { throw MacroError.notAStaticURL }        // a build error, not a crash
    return "URL(string: \(literal))!"
  }
}

final class Storage {                     // private, final, single owner
  var pixels: [UInt8]
  init(pixels: [UInt8]) { self.pixels = pixels }
  func copy() -> Storage { Storage(pixels: pixels) }
}

struct Bitmap {
  private var storage: Storage            // must be a var stored property

  init(pixels: [UInt8]) { storage = Storage(pixels: pixels) }

  private mutating func makeUnique() {
    if !isKnownUniquelyReferenced(&storage) {
      storage = storage.copy()            // somebody else holds it — clone
    }
  }

  subscript(index: Int) -> UInt8 {
    get { storage.pixels[index] }
    set {
      makeUnique()                        // ✅ copy exactly once, on first write
      storage.pixels[index] = newValue
    }
  }

  mutating func invert() {
    makeUnique()
    for i in storage.pixels.indices { storage.pixels[i] = 255 - storage.pixels[i] }
  }

  var isUniquelyOwned: Bool { mutating get { isKnownUniquelyReferenced(&storage) } }
}

