import SwiftUI

// ❌ One expression: the literals are still open (Int? Double? CGFloat?), + is
// overloaded dozens of times, and each ternary makes the solver try both
// branches against every candidate that is still standing.
func slowPadding(isCompact: Bool, hasIcon: Bool, iconWidth: CGFloat, inset: CGFloat) -> CGFloat {
  (isCompact ? 8 : 16) + (hasIcon ? iconWidth : 0) + 2 * 4 - inset / 2
}

// ✅ Same arithmetic, split and annotated. Each annotation removes a whole
// branch from the constraint solver's search.
func fastPadding(isCompact: Bool, hasIcon: Bool, iconWidth: CGFloat, inset: CGFloat) -> CGFloat {
  let base: CGFloat = isCompact ? 8 : 16
  let icon: CGFloat = hasIcon ? iconWidth : 0
  let gutter: CGFloat = 8
  return base + icon + gutter - inset / 2
}

