// Move the storage behind a reference and the wrapper itself never changes.
@propertyWrapper
struct Boxed<Value> {
  private final class Box { var value: Value; init(_ v: Value) { value = v } }
  private let box: Box

  init(wrappedValue: Value) { box = Box(wrappedValue) }

  var wrappedValue: Value {
    get { box.value }
    nonmutating set { box.value = newValue }   // ✅ legal on a let instance
  }
}

