import Foundation

// A query type where interpolated values become bound parameters, never SQL text.
struct SQLQuery: ExpressibleByStringInterpolation {
  let sql: String
  let bindings: [any Encodable]

  struct StringInterpolation: StringInterpolationProtocol {
    var sql = ""
    var bindings: [any Encodable] = []

    init(literalCapacity: Int, interpolationCount: Int) {
      sql.reserveCapacity(literalCapacity + interpolationCount * 2)
    }

    mutating func appendLiteral(_ literal: String) { sql += literal }

    // \(value) — the value leaves the string entirely; only a placeholder stays
    mutating func appendInterpolation(_ value: some Encodable) {
      bindings.append(value)
      sql += "?"
    }

    // \(raw: "created_at DESC") — splicing is possible, but you have to ask for it
    mutating func appendInterpolation(raw text: String) { sql += text }

    // extra arguments and labels are just another overload
    mutating func appendInterpolation(column name: String, quoted: Bool = true) {
      sql += quoted ? "\"\(name)\"" : name
    }
  }

  init(stringLiteral value: String) { sql = value; bindings = [] }

  init(stringInterpolation: StringInterpolation) {
    sql = stringInterpolation.sql
    bindings = stringInterpolation.bindings
  }
}

