public struct Bucketer<Key: Hashable> {
  // An inlinable body may only reference public or @usableFromInline symbols.
  @usableFromInline let capacity: Int

  public init(capacity: Int) { self.capacity = capacity }

  // ❌ Body stays inside the module. A client in another module links the
  // unspecialised copy: Key's layout is unknown there, so values move through
  // the value witness table and every hash is a witness-table call.
  public func histogram(_ keys: [Key]) -> [Key: Int] {
    keys.reduce(into: .init(minimumCapacity: capacity)) { $0[$1, default: 0] += 1 }
  }

  // ✅ Body ships in the module interface, so the client specialises it for its
  // own concrete Key and inlines the hashing.
  @inlinable
  public func fastHistogram(_ keys: [Key]) -> [Key: Int] {
    keys.reduce(into: .init(minimumCapacity: capacity)) { $0[$1, default: 0] += 1 }
  }

  // Pre-bake the instantiations you know are hot, without publishing the body.
  @_specialize(where Key == String)
  @_specialize(where Key == Int)
  public func bakedHistogram(_ keys: [Key]) -> [Key: Int] {
    keys.reduce(into: .init(minimumCapacity: capacity)) { $0[$1, default: 0] += 1 }
  }
}

