import Darwin

struct FileDescriptor: ~Copyable {
  private let fd: Int32

  init?(opening path: String) {
    let handle = open(path, O_RDONLY)
    guard handle >= 0 else { return nil }
    fd = handle
  }

  // borrowing: read-only access for the call, nothing is transferred.
  borrowing func size() -> Int {
    Int(lseek(fd, 0, SEEK_END))
  }

  // consuming: the caller's binding dies here. `discard self` suppresses deinit
  // so the descriptor is not closed a second time.
  consuming func close() {
    Darwin.close(fd)
    discard self
  }

  deinit { Darwin.close(fd) }   // runs when the single owner goes out of scope
}

func totalSize(_ file: borrowing FileDescriptor) -> Int { file.size() }

func run() {
  guard let file = FileDescriptor(opening: "/etc/hosts") else { return }
  print(totalSize(file))     // borrowed — still ours afterwards
  file.close()               // consumed here
  // print(totalSize(file))  // ❌ 'file' used after consume
}                            // deinit does not run: close() discarded self

