// ❌ Before parameter packs: one hand-written overload per arity, forever.
// func combine<A, B>(_ a: Store<A>, _ b: Store<B>) -> (A, B) { (a.value, b.value) }
// func combine<A, B, C>(_ a: Store<A>, _ b: Store<B>, _ c: Store<C>) -> (A, B, C) { ... }

// ✅ One declaration, every arity. `repeat` expands the pack in the parameter
// list, in the return type, and in the returned tuple value.
func combine<each Value>(_ stores: repeat Store<each Value>) -> (repeat each Value) {
  (repeat (each stores).value)
}

