// Constraints apply to the whole pack, and Swift 6 lets you iterate one.
func encodeAll<each T: Encodable>(_ values: repeat each T) throws -> [Data] {
  let encoder = JSONEncoder()
  var out: [Data] = []
  for value in repeat each values {          // pack iteration
    out.append(try encoder.encode(value))
  }
  return out
}

// A pack cannot be stored; store the expanded tuple instead.
struct Snapshot<each Value> {
  let values: (repeat each Value)            // ✅
  // let raw: repeat each Value              // ❌ not a type
}

let boxed = Snapshot(values: combine(name, age, isAdmin))

struct Settings {
  var isDarkMode = false
  var fontSize = 14
  var username = ""
}

// ❌ Different Value types, so there is no single element type for the array:
// let rows: [WritableKeyPath<Settings, ???>] = [\.isDarkMode, \.fontSize]

// ❌ Erasing compiles, but the write is gone and reads come back as Any.
let readOnly: [PartialKeyPath<Settings>] = [\.isDarkMode, \.fontSize, \.username]
print(Settings()[keyPath: readOnly[1]])        // 14, statically typed Any

// ✅ 1. Keep the value type in the case.
enum Row {
  case toggle(String, WritableKeyPath<Settings, Bool>)
  case stepper(String, WritableKeyPath<Settings, Int>)
  case text(String, WritableKeyPath<Settings, String>)
}

let rows: [Row] = [
  .toggle("Dark mode", \.isDarkMode),
  .stepper("Font size", \.fontSize),
  .text("Username", \.username),
]

// ✅ 2. Capture the typed key path at construction; the row itself is concrete.
struct Field {
  let title: String
  let read: (Settings) -> String
  let write: (inout Settings, String) -> Void

  init<V: LosslessStringConvertible>(_ title: String,
                                     _ keyPath: WritableKeyPath<Settings, V>) {
    self.title = title
    read = { String($0[keyPath: keyPath]) }
    write = { settings, text in
      if let value = V(text) { settings[keyPath: keyPath] = value }
    }
  }
}

var settings = Settings()
let fields = [Field("Font size", \.fontSize), Field("Username", \.username)]
fields[0].write(&settings, "18")
print(fields[0].read(settings))                // 18

// Key paths are Hashable — a fine key for labels or validation rules.
let labels: [PartialKeyPath<Settings>: String] = [\.fontSize: "Font size"]
